record Res(String name) implements AutoCloseable {
    Res { System.out.println("open " + name); }
    public void close() { System.out.println("close " + name); }
}
public class Main {
    public static void main(String[] args) {
        try (Res a = new Res("A"); Res b = new Res("B")) {
            System.out.println("body");
            throw new IllegalStateException("boom");
        } catch (IllegalStateException e) {
            System.out.println("caught " + e.getMessage());
        } finally {
            System.out.println("finally");
        }
        System.out.println("end");
    }
}

public class Main {
    static class Gate implements AutoCloseable {
        public void close() throws Exception {
            System.out.println("closing");
            throw new Exception("close failed");
        }
    }
    public static void main(String[] args) {
        try (Gate g = new Gate()) {
            throw new IllegalStateException("body failed");
        } catch (Exception e) {
            System.out.println(e.getMessage());
            Throwable[] hidden = e.getSuppressed();
            System.out.println(hidden.length + " " + hidden[0].getMessage());
        }
    }
}

