import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        int[] seen = {0};
        int first = IntStream.rangeClosed(1, 10)
            .peek(n -> seen[0]++)
            .filter(n -> n % 3 == 0)
            .findFirst()
            .getAsInt();
        System.out.println(first + " after " + seen[0]);
        seen[0] = 0;
        boolean all = IntStream.of(4, 7, 9, 12)
            .peek(n -> seen[0]++)
            .allMatch(n -> n % 2 == 0);
        System.out.println(all + " after " + seen[0]);
        long count = IntStream.range(0, 5).peek(n -> seen[0]++).count();
        System.out.println(count + " " + seen[0]);
    }
}

